// Find the service_type select element
const selects = document.querySelectorAll('select');
const result = [];
selects.forEach(s => {
  if (s.name === 'service_type' || s.id?.includes('service') || s.closest('[name="service_type"]')) {
    result.push({ name: s.name, id: s.id, options: Array.from(s.options).map(o => ({val: o.value, text: o.text})) });
  }
});
// Also check via the field widget
const serviceField = document.querySelector('[name="service_type"]');
result.push({ html: serviceField ? serviceField.innerHTML.substring(0, 500) : 'not found' });
result;

